package main

import (
	"fmt"
	"regexp"
)

// Test if the subdomain validation works correctly
func main() {
	testCases := []string{"valid-subdomain", "-invalid", "invalid-", "in..valid", "valid123"}
	for _, testCase := range testCases {
		isValid := isValidSubdomain(testCase)
		fmt.Printf("Subdomain: %s, Valid: %t\n", testCase, isValid)
	}
}

// isValidSubdomain checks if the provided subdomain prefix is valid.
func isValidSubdomain(subdomain string) bool {
	if len(subdomain) == 0 || len(subdomain) > 63 {
		return false
	}
	re := regexp.MustCompile(`^(?!-)[a-zA-Z0-9-]{1,63}(?<!-)$`)
	return re.MatchString(subdomain) && !strings.Contains(subdomain, "..")
}
